const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');const root=path.resolve(__dirname,'..'),read=p=>fs.readFileSync(path.join(root,p),'utf8');
test('both marketplace entry routes resolve to the same HTML and module, while ranch and direct Prefabs routes remain available',()=>{const routes=JSON.parse(read('vercel.json')).rewrites;const q=routes.findIndex(r=>r.source==='/scene-generator'&&r.has?.some(h=>h.key==='scene'&&h.value==='market'));const ranch=routes.findIndex(r=>r.source==='/scene-generator'&&!r.has);assert(q>=0&&q<ranch);assert.equal(routes[q].destination,'/market.html');assert(routes.some(r=>r.source==='/market'&&r.destination==='/market.html'));assert(read('market.html').includes('src="/market.js"'));assert(read('market.js').includes("from './market-scene.js'"));assert(read('tile-editor.html').includes('/scene-selector.js'));assert(read('scene-selector.js').includes('/scene-generator?scene=market'));assert(routes.some(r=>r.source==='/scene-generator/prefabs'&&r.destination==='/sets.html'));assert(!read('navigation.js').includes('/scene-generator/prefabs'));});
test('one shared scene composes the simulation geometry and decoration; both entry points share the saved-day key',()=>{const source=read('market-scene.js');assert(source.includes("from './market-engine.js'"));assert(source.includes("from './market-art.js'"));assert(source.includes("from './market-dressing.js'"));assert(read('market.js').includes("localStorage.setItem('ranch-market-v2'"));assert(read('market.html').includes('id="market-roofs"'));});
